long long modpow(long long a, long long e, long long mod) {
    if (mod <= 0 || e < 0) throw invalid_argument("mod deve ser positivo e expoente não negativo");
    a %= mod;
    long long r = 1 % mod;
    while (e) {
        if (e & 1) r = (__int128)r * a % mod;
        a = (__int128)a * a % mod;
        e >>= 1;
    }
    return r;
}

long long extgcd(long long a, long long b, long long& x, long long& y) {
    if (!b) { x = 1; y = 0; return a; }
    long long x1, y1;
    long long g = extgcd(b, a % b, x1, y1);
    x = y1; y = x1 - (a / b) * y1;
    return g;
}

vector<bool> prime(n + 1, true);
if (n >= 0) prime[0] = false;
if (n >= 1) prime[1] = false;
for (int p = 2; 1LL * p * p <= n; ++p)
    if (prime[p])
        for (long long x = 1LL * p * p; x <= n; x += p) prime[x] = false;

struct Point { long long x, y; };
__int128 cross(Point a, Point b, Point c) {
    return (__int128)(b.x-a.x)*(c.y-a.y) - (__int128)(b.y-a.y)*(c.x-a.x);
}
